<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { game } from '../../gameManager.js';
  import { localizePokemonName } from '../../constants/pokemonNameI18n.ts';
  import { getPokemonSpriteUrl } from '../lib/cardSprites.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';
  import {
    buildTrainerCardModel, resolveTrainerCardSelection, trainerCardOwnedCreatures, trainerCardText,
    type TrainerCardModel, type TrainerCardOwnedCreature,
  } from '../lib/trainerCardModel.ts';
  import {
    normalizeTrainerCardPreferences, effectiveTrainerCardPreferences, trainerCardUnlocks,
    TRAINER_CARD_THEMES, TRAINER_CARD_FRAMES, TRAINER_CARD_BACKGROUNDS, TRAINER_CARD_STATS,
    TRAINER_CARD_FRAME_UNLOCKS, trainerCardCosmeticUnlocked,
    type TrainerCardPreferences, type TrainerCardFormat, type TrainerCardSide,
  } from '../lib/trainerCardPreferences.ts';
  import { renderTrainerCardCanvas, trainerCardLayout, trainerCardPng, retryTrainerCardImages, type TrainerCardRect } from '../lib/trainerCardCanvas.ts';
  import { trainerCardPalette, trainerCardCosmeticImage, trainerCardCosmeticThumbnail } from '../lib/trainerCardCosmetics.ts';

  const { trackGameLanguage } = useGameLanguageTick();
  let view = $state<TrainerCardSide | 'personal'>('front');
  let format = $state<TrainerCardFormat>('portrait');
  let preferences = $state<TrainerCardPreferences>(normalizeTrainerCardPreferences(null));
  let model = $state.raw<TrainerCardModel | null>(null);
  let owned = $state.raw<TrainerCardOwnedCreature[]>([]);
  let canvas = $state<HTMLCanvasElement>();
  let personalContent = $state<HTMLDivElement>();
  let picker = $state<HTMLDialogElement>();
  let pickerMode = $state<'partner' | 'favorites'>('favorites');
  let query = $state('');
  let visibleCount = $state(48);
  let exporting = $state(false);
  let previewLoading = $state(false);
  let missingSprites = $state(false);
  let message = $state('');
  let retryVersion = $state(0);
  const cosmeticKinds = ['theme', 'background', 'frame'] as const;
  let cosmeticSections = $state({ theme: true, background: false, frame: false });
  let hydrated = false;

  function t(key: string, params?: Record<string, string | number>): string {
    trackGameLanguage();
    return game ? trainerCardText(game, key, params) : key;
  }

  let unlocks = $derived.by(() => {
    void model;
    return trainerCardUnlocks(game ?? {});
  });
  let favoriteUids = $derived.by(() => game
    ? resolveTrainerCardSelection(game, preferences, owned).favorites.map(entry => entry.creature.uid) : []);
  let layout = $derived(trainerCardLayout(format));
  let profileSprites = $derived.by(() => {
    void model;
    return game?.getPlayerSpriteCatalog?.() ?? [];
  });

  function label(entry: TrainerCardOwnedCreature): string {
    return localizePokemonName(entry.creature.name, model?.language ?? 'fr');
  }
  function searchText(value: string): string {
    return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  }
  let filteredOwned = $derived(owned.filter(entry =>
    searchText(label(entry)).includes(searchText(query)) || searchText(entry.creature.name).includes(searchText(query))));

  function refresh(): void {
    if (!game || !hydrated) return;
    owned = trainerCardOwnedCreatures(game);
    model = buildTrainerCardModel(game, preferences);
  }

  function savePreferences(patch: Partial<TrainerCardPreferences>): void {
    if (!game) return;
    preferences = effectiveTrainerCardPreferences(normalizeTrainerCardPreferences({ ...preferences, ...patch }), trainerCardUnlocks(game));
    game.trainerCardPreferences = normalizeTrainerCardPreferences(preferences);
    game.saveGame({ immediate: true, reason: 'trainer_card' });
    refresh();
  }

  function refreshPersonal(): void {
    if (!game || !personalContent) return;
    game.renderMasteryTrainerCard();
    personalContent.querySelectorAll<HTMLElement>('[data-tooltip-title]').forEach(node => {
      node.setAttribute('role', 'button');
      node.tabIndex = 0;
      node.setAttribute('aria-label', node.getAttribute('data-tooltip-title') ?? '');
    });
  }

  async function selectView(next: typeof view): Promise<void> {
    view = next;
    message = '';
    refresh();
    if (next === 'personal') { await tick(); refreshPersonal(); }
  }

  async function openPicker(mode: typeof pickerMode): Promise<void> {
    refresh();
    pickerMode = mode;
    query = '';
    visibleCount = 48;
    await tick();
    picker?.showModal();
  }

  function selectPokemon(entry: TrainerCardOwnedCreature): void {
    const uid = entry.creature.uid;
    if (pickerMode === 'partner') {
      savePreferences({ partnerUid: uid });
      picker?.close();
    } else if (favoriteUids.includes(uid)) {
      savePreferences({ favoriteUids: favoriteUids.filter(value => value !== uid) });
    } else if (favoriteUids.length < 8) {
      savePreferences({ favoriteUids: [...favoriteUids, uid] });
    }
  }

  function showPokemon(uid: string | undefined): void {
    if (!uid || !game) { void openPicker('favorites'); return; }
    const entry = trainerCardOwnedCreatures(game).find(candidate => candidate.creature.uid === uid);
    if (entry) void game.showCreatureModal(entry.index, entry.location);
    else refresh();
  }

  function hitStyle(rect: TrainerCardRect): string {
    return `left:${rect.x / layout.width * 100}%;top:${rect.y / layout.height * 100}%;width:${rect.width / layout.width * 100}%;height:${rect.height / layout.height * 100}%`;
  }

  async function exportPng(): Promise<void> {
    if (!model || view === 'personal' || exporting) return;
    const snapshot = model;
    const side = view;
    const selectedFormat = format;
    exporting = true;
    message = '';
    try {
      retryTrainerCardImages();
      const png = await trainerCardPng(snapshot, selectedFormat, side);
      const url = URL.createObjectURL(png);
      const anchor = document.createElement('a');
      anchor.href = url;
      const name = snapshot.name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9_-]+/gi, '-').slice(0, 40) || 'trainer';
      anchor.download = `poketime-${name}-${side}-${selectedFormat}.png`;
      anchor.click();
      setTimeout(() => URL.revokeObjectURL(url), 30000);
      message = t('exportDone');
    } catch {
      message = t('exportError');
    } finally { exporting = false; }
  }

  function updateProfile(patch: { name?: string; spriteId?: string }): void {
    if (!game) return;
    game.setPlayerProfile({ ...game.playerProfile, ...patch }, { save: false });
    game.saveGame({ immediate: true, reason: 'trainer_card_profile' });
    refresh();
  }

  function retrySprites(): void {
    retryTrainerCardImages();
    retryVersion += 1;
  }

  type CosmeticKind = 'theme' | 'background' | 'frame';
  function cosmeticName(kind: CosmeticKind, id: string): string {
    return t(kind === 'theme' ? id : `${kind}_${id}`);
  }
  function cosmeticRequirement(kind: CosmeticKind, id: string): string {
    const requirement = kind === 'frame' ? TRAINER_CARD_FRAME_UNLOCKS[id as TrainerCardPreferences['frame']]
      : kind === 'theme' && (id === 'league' || id === 'shiny') ? id : undefined;
    const keys = { league: 'unlockLeague', shiny: 'unlockShiny', bronze: 'unlockBronze', tower: 'unlockTower', starlight: 'unlockStarlight', legend: 'unlockLegend' };
    return requirement ? t(keys[requirement]) : t('included');
  }
  function chooseCosmetic(kind: CosmeticKind, id: string): void {
    if (kind === 'theme') savePreferences({ theme: id as TrainerCardPreferences['theme'], accent: null });
    else if (kind === 'frame') savePreferences({ frame: id as TrainerCardPreferences['frame'] });
    else savePreferences({ background: id as TrainerCardPreferences['background'] });
  }

  $effect(() => {
    trackGameLanguage();
    if (hydrated) refresh();
  });

  $effect(() => {
    const target = canvas;
    const snapshot = model;
    const side = view;
    const selectedFormat = format;
    void retryVersion;
    if (!target || !snapshot || side === 'personal') return;
    let cancelled = false;
    previewLoading = true;
    const buffer = document.createElement('canvas');
    void renderTrainerCardCanvas(buffer, snapshot, selectedFormat, side).then(result => {
      if (cancelled) return;
      target.width = buffer.width;
      target.height = buffer.height;
      target.getContext('2d')?.drawImage(buffer, 0, 0);
      missingSprites = result.missingSprites > 0;
      previewLoading = false;
    }).catch(() => {
      if (!cancelled) { missingSprites = true; previewLoading = false; }
    });
    return () => { cancelled = true; };
  });

  onMount(() => {
    if (!game) return;
    preferences = effectiveTrainerCardPreferences(normalizeTrainerCardPreferences(game.trainerCardPreferences), trainerCardUnlocks(game));
    hydrated = true;
    refresh();
    refreshPersonal();
    const timer = setInterval(() => {
      if (document.getElementById('masteryModal')?.classList.contains('show')) refresh();
    }, 1000);
    const badges = personalContent;
    const showBadge = (event: Event): void => {
      const node = event.target instanceof Element ? event.target.closest<HTMLElement>('[data-tooltip-title]') : null;
      if (!node || !badges?.contains(node) || !game) return;
      if (event instanceof KeyboardEvent) {
        if (event.key !== 'Enter' && event.key !== ' ') return;
        event.preventDefault();
        const bounds = node.getBoundingClientRect();
        game.scheduleTooltip(new MouseEvent('click', { clientX: bounds.left + bounds.width / 2, clientY: bounds.bottom }), node.dataset.tooltipTitle ?? '', node.dataset.tooltipDesc ?? '');
      } else game.scheduleTooltip(event as MouseEvent, node.dataset.tooltipTitle ?? '', node.dataset.tooltipDesc ?? '');
    };
    badges?.addEventListener('click', showBadge);
    badges?.addEventListener('keydown', showBadge);
    return () => { clearInterval(timer); badges?.removeEventListener('click', showBadge); badges?.removeEventListener('keydown', showBadge); };
  });
</script>

<div class="trainer-card-editor">
  <div class="card-toolbar">
    <div class="card-tabs" role="group" aria-label={t('trainerCard')}>
      <button type="button" class:active={view === 'front'} aria-pressed={view === 'front'} onclick={() => selectView('front')}>{t('front')}</button>
      <button type="button" class:active={view === 'back'} aria-pressed={view === 'back'} onclick={() => selectView('back')}>{t('back')}</button>
      <button type="button" class:active={view === 'personal'} aria-pressed={view === 'personal'} onclick={() => selectView('personal')}>{t('personal')}</button>
    </div>
    {#if view !== 'personal'}
      <button type="button" class="export-button" disabled={exporting || !model} onclick={exportPng}>{exporting ? t('exporting') : t('export')}</button>
    {/if}
  </div>

  {#if view !== 'personal'}
    <label class="format-field"><span>{t('format')}</span><select aria-label={t('format')} bind:value={format}><option value="portrait">{t('portrait')}</option><option value="landscape">{t('landscape')}</option></select></label>
    {#if model}
      <div class="preview-stage">
        <div class="card-preview" class:landscape={format === 'landscape'} style:aspect-ratio={`${layout.width} / ${layout.height}`}>
          <canvas bind:this={canvas} aria-label={t('preview', { name: model.name, side: t(view) })}></canvas>
          {#if view === 'front'}
            <button type="button" class="card-hit partner-hit" style={hitStyle(layout.partner)} aria-label={model.partner ? t('viewPokemon', { name: model.partner.name, prestige: model.partner.prestige }) : t('choosePartner')} onclick={() => model?.partner ? showPokemon(model.partner.uid) : openPicker('partner')}></button>
            {#each layout.favorites as rect, index}
              {@const pokemon = model.favorites[index]}
              <button type="button" class="card-hit" style={hitStyle(rect)} aria-label={pokemon ? t('viewPokemon', { name: pokemon.name, prestige: pokemon.prestige }) : `${t('emptySlot')} ${index + 1}`} onclick={() => showPokemon(pokemon?.uid)}></button>
            {/each}
          {/if}
        </div>
      </div>
      {#if previewLoading}<p class="card-note" role="status">{t('loadingSprites')}</p>{/if}
      {#if missingSprites && !previewLoading}<p class="card-note">{t('spriteError')} <button type="button" class="text-button" onclick={retrySprites}>{t('retry')}</button></p>{/if}
      <div class="selection-actions"><button type="button" onclick={() => openPicker('partner')}>{t('choosePartner')}</button><button type="button" onclick={() => openPicker('favorites')}>{t('editFavorites')} · {favoriteUids.length}/8</button></div>
      <details class="customization">
        <summary>{t('customize')}</summary>
        <div class="editor-fields">
          <label><span>{t('profileName')}</span><input type="text" value={model.name} maxlength="20" onchange={event => updateProfile({ name: event.currentTarget.value })}></label>
          <label><span>{t('avatar')}</span><select value={game?.playerProfile.spriteId} onchange={event => updateProfile({ spriteId: event.currentTarget.value })}>{#each profileSprites as avatar}<option value={avatar.id}>{avatar.label}</option>{/each}</select></label>
          <label class="full-width"><span>{t('title')}</span><input type="text" value={preferences.title} placeholder={t('defaultTitle')} maxlength="36" onchange={event => savePreferences({ title: event.currentTarget.value })}></label>
          <label><span>{t('accent')}</span><div class="accent-field"><input aria-label={t('accent')} type="color" value={preferences.accent ?? trainerCardPalette(preferences.theme).shell} onchange={event => savePreferences({ accent: event.currentTarget.value })}><button type="button" class="text-button" onclick={() => savePreferences({ accent: null })}>{t('resetAccent')}</button></div></label>
          <label class="full-width"><span>{t('pokedexMode')}</span><select value={preferences.pokedexMode} onchange={event => savePreferences({ pokedexMode: event.currentTarget.value as TrainerCardPreferences['pokedexMode'] })}>{#each ['both', 'normal', 'shiny'] as mode}<option value={mode}>{t(`dex_${mode}`)}</option>{/each}</select></label>
        </div>
        <p class="card-note">{t('cosmeticsHint')}</p>
        {#each cosmeticKinds as kind}
          <details class="cosmetic-collection" bind:open={cosmeticSections[kind]} data-cosmetic-kind={kind}>
            <summary>{t(kind)}<span>{cosmeticName(kind, preferences[kind])}</span></summary>
            <div class="cosmetic-gallery" role="group" aria-label={t(kind)}>
              {#each (kind === 'theme' ? TRAINER_CARD_THEMES : kind === 'frame' ? TRAINER_CARD_FRAMES : TRAINER_CARD_BACKGROUNDS) as id}
                {@const unlocked = kind === 'background' || trainerCardCosmeticUnlocked(kind, id, unlocks)}
                {@const selected = preferences[kind] === id}
                <button type="button" class="cosmetic-choice" class:chosen={selected} class:locked={!unlocked} disabled={!unlocked} aria-pressed={selected} aria-label={cosmeticName(kind, id)} title={cosmeticRequirement(kind, id)} data-cosmetic-id={id} onclick={() => chooseCosmetic(kind, id)}>
                  <span class="cosmetic-art" class:pattern-preview={kind === 'background' && ['radar', 'grid', 'plain'].includes(id)} class:frame-preview={kind === 'frame'} data-pattern={id}><img src={trainerCardCosmeticThumbnail(trainerCardCosmeticImage(kind, id))} alt="" width="320" height="160" loading="lazy" decoding="async">{#if selected}<span class="cosmetic-mark" aria-hidden="true">✓</span>{:else if !unlocked}<span class="cosmetic-mark" aria-hidden="true">◇</span>{/if}</span>
                  <span class="cosmetic-name">{cosmeticName(kind, id)}</span>
                  <span class="cosmetic-condition">{unlocked ? t('available') : cosmeticRequirement(kind, id)}</span>
                </button>
              {/each}
            </div>
          </details>
        {/each}
        <div class="stats-editor"><h3>{t('publicStats')}</h3><div class="editor-fields">{#each preferences.statKeys as selected, index}<label><span>{index + 1}</span><select value={selected} onchange={event => { const statKeys = [...preferences.statKeys]; statKeys[index] = event.currentTarget.value as typeof selected; savePreferences({ statKeys }); }}>{#each TRAINER_CARD_STATS as stat}<option value={stat} disabled={stat !== selected && preferences.statKeys.includes(stat)}>{t(`stat_${stat}`)}</option>{/each}</select></label>{/each}</div></div>
      </details>
    {/if}
  {/if}

  <section class="personal-card" hidden={view !== 'personal'} data-shareable="false" data-export-exclude>
    <div class="personal-heading"><h3>{t('personal')}</h3><span>{t('personalOnly')}</span></div>
    <div id="masteryTrainerCardContent" class="legacy-personal" bind:this={personalContent}></div>
  </section>
  {#if message}<p class="card-note" role="status">{message}</p>{/if}
</div>

<dialog class="pokemon-picker" bind:this={picker} aria-labelledby="trainerCardPickerTitle">
  <div class="picker-header"><h2 id="trainerCardPickerTitle">{pickerMode === 'partner' ? t('choosePartner') : t('editFavorites')}</h2><button type="button" onclick={() => picker?.close()}>{t('close')}</button></div>
  <div class="picker-content">
    <label class="search-field"><span>{t('search')}</span><input type="search" value={query} oninput={event => { query = event.currentTarget.value; visibleCount = 48; }}></label>
    {#if pickerMode === 'favorites'}<p class="picker-count">{t('selected', { count: favoriteUids.length })}</p>{/if}
    <div class="picker-grid">
      {#each filteredOwned.slice(0, visibleCount) as entry (entry.creature.uid)}
        {@const selected = pickerMode === 'partner' ? model?.partner?.uid === entry.creature.uid : favoriteUids.includes(entry.creature.uid)}
        <button type="button" class="picker-pokemon" class:selected aria-pressed={selected} disabled={pickerMode === 'favorites' && !selected && favoriteUids.length >= 8} onclick={() => selectPokemon(entry)}>
          <img src={getPokemonSpriteUrl(entry.creature.name, !!entry.creature.isShiny, false, { animatedConfig: { all: false, active: false, team: false, pension: false } })} alt="" width="64" height="64" loading="lazy">
          <span class="picker-name">{label(entry)}{entry.creature.isShiny ? ' ✦' : ''}</span>
          <span class="picker-level">{t('level')} {entry.creature.level} · <img src="img/prestige-star.png" alt={t('prestige')} width="10" height="10"> {entry.creature.prestige}</span>
        </button>
      {/each}
    </div>
    {#if filteredOwned.length === 0}<p class="card-note">{owned.length === 0 ? t('noOwned') : t('noResults')}</p>{/if}
    <div class="picker-footer">{#if filteredOwned.length > visibleCount}<button type="button" onclick={() => visibleCount += 48}>{t('showMore')}</button>{/if}<button type="button" onclick={() => picker?.close()}>{t('done')}</button></div>
  </div>
</dialog>

<style>
