  .trainer-card-editor [hidden] { display: none !important; }
  .card-toolbar, .selection-actions, .picker-header, .picker-footer { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
  .card-toolbar { margin-bottom: 12px; }
  button, input, select { font-family: var(--font-ui, Inter, sans-serif); }
  button { color: #e2e8f0; background: linear-gradient(#363a45, #262932); border: 1px solid #14161c; border-radius: 6px; padding: 8px 11px; font-size: 11px; cursor: pointer; box-shadow: inset 0 1px 0 #ffffff24; }
  button:hover { background: #414753; }
  button:disabled { opacity: .5; cursor: default; }
