  .format-field > span, label > span { font-size: 11px; color: #aab3c5; }
  select, input[type=text], input[type=search] { min-width: 0; max-width: 100%; color: #f8fafc; background: #151821; border: 1px solid #4b5363; border-radius: 5px; padding: 8px; font-size: 12px; }
  .preview-stage { display: flex; justify-content: center; padding: 18px 9px; border-radius: 12px; background: #e8e7e0; background-image: radial-gradient(#c5c8bd .8px, transparent .8px); background-size: 14px 14px; }
