import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';
import { localizePokemonName } from '../../constants/pokemonNameI18n.ts';
import { getPokemonSpriteUrl } from './cardSprites.ts';
import { NON_DEX_SPRITE_PLACEHOLDERS, POKEMON_SPRITE_IDS } from '../../constants/balance/dexAndCapture.ts';
import {
  effectiveTrainerCardPreferences, normalizeTrainerCardPreferences, trainerCardUnlocks,
  TRAINER_CARD_THEMES,
  type TrainerCardPreferences,
} from './trainerCardPreferences.ts';

const dexIds: Record<string, number> = POKEMON_SPRITE_IDS;

export interface TrainerCardOwnedCreature {
  location: string;
  index: number;
  creature: CreatureData;
}

export interface TrainerCardPokemon {
  uid: string;
  name: string;
  sprite: string;
  type: string;
  secondaryType: string | null;
  level: number;
  prestige: number;
  shiny: boolean;
  dexNumber: number | null;
}

/** Only public card fields enter the PNG renderer. Personal badge tooltips stay in the game. */
export interface TrainerCardModel {
  language: 'fr' | 'en';
  name: string;
  avatar: string;
  title: string;
  grade: { name: string; color: string };
  score: number;
  partner: TrainerCardPokemon | null;
  favorites: (TrainerCardPokemon | null)[];
  badges: number;
  tower: number;
  pokedex: { normal: number; shiny: number };
  stats: { label: string; value: number }[];
  stamps: { title: string; subtitle: string }[];
  preferences: TrainerCardPreferences;
  labels: Record<string, string>;
}

export function trainerCardText(game: GameRuntime, key: string, params?: Record<string, string | number>): string {
  return game.t(`trainerCard.${key}`, params);
}

export function trainerCardOwnedCreatures(game: GameRuntime): TrainerCardOwnedCreature[] {
  const entries = typeof game.getAllCreaturesWithLocation === 'function'
    ? game.getAllCreaturesWithLocation()
    : [
      ...(game.playerTeam ?? []).map((creature, index) => ({ creature, index, location: 'team' })),
      ...(game.storage ?? []).map((creature, index) => ({ creature, index, location: 'storage' })),
      ...(game.pension ?? []).map((creature, index) => ({ creature, index, location: 'pension' })),
    ];
  const seen = new Set<string>();
  return entries.filter(entry => {
    const uid = entry.creature?.uid;
    if (!uid || seen.has(uid)) return false;
    seen.add(uid);
    return true;
  });
}

export function resolveTrainerCardSelection(
  game: GameRuntime,
  preferences: TrainerCardPreferences,
  owned = trainerCardOwnedCreatures(game),
): { favorites: TrainerCardOwnedCreature[]; partner: TrainerCardOwnedCreature | null } {
  const byUid = new Map(owned.map(entry => [entry.creature.uid, entry]));
  const resolve = (uid: string) => byUid.get(uid)
    ?? byUid.get(typeof game.resolveLoadoutUid === 'function' ? game.resolveLoadoutUid(uid) : uid);
  const initial = [
    ...owned.filter(entry => entry.creature.isFavorite),
    ...owned.filter(entry => entry.location === 'team'),
    ...owned,
  ];
  const candidates = preferences.favoriteUids === null
    ? initial : preferences.favoriteUids.map(resolve).filter((entry): entry is TrainerCardOwnedCreature => !!entry);
  const seen = new Set<string>();
  const favorites = candidates.filter(entry => {
    if (seen.has(entry.creature.uid)) return false;
    seen.add(entry.creature.uid);
    return true;
  }).slice(0, 8);
  return {
    favorites,
    partner: (preferences.partnerUid ? resolve(preferences.partnerUid) : null) ?? favorites[0] ?? owned[0] ?? null,
  };
}

export function buildTrainerCardModel(game: GameRuntime, rawPreferences: unknown = game.trainerCardPreferences): TrainerCardModel {
  const language = game.language === 'fr' ? 'fr' : 'en';
  const preferences = effectiveTrainerCardPreferences(normalizeTrainerCardPreferences(rawPreferences), trainerCardUnlocks(game));
  const selected = resolveTrainerCardSelection(game, preferences);
  const pokemon = (entry: TrainerCardOwnedCreature): TrainerCardPokemon => {
    const creature = entry.creature;
    return {
      uid: creature.uid,
      name: localizePokemonName(creature.name, language),
      sprite: getPokemonSpriteUrl(creature.name, !!creature.isShiny, false, { animatedConfig: { all: false, active: false, team: false, pension: false } }),
      type: String(creature.type || 'normal').toLowerCase(),
      secondaryType: creature.secondaryType ? String(creature.secondaryType).toLowerCase() : null,
      level: Number(creature.level) || 1,
      prestige: Number(creature.prestige) || 0,
      shiny: !!creature.isShiny,
      dexNumber: Number(dexIds[creature.name]) || null,
    };
  };
  const total = Object.keys(POKEMON_SPRITE_IDS).filter(name => !NON_DEX_SPRITE_PLACEHOLDERS.has(name)).length;
  const normal = new Set<string>();
  const shiny = new Set<string>();
  Object.values(game.pokedex ?? {}).forEach(entry => {
    if (!entry?.name || NON_DEX_SPRITE_PLACEHOLDERS.has(entry.name)) return;
    if (entry.discovered) normal.add(entry.name);
    if (entry.hasShiny) shiny.add(entry.name);
  });
  const percentage = (count: number) => total > 0 ? Math.min(100, count / total * 100) : 0;
  const score = typeof game.computeTrainerScore === 'function' ? game.computeTrainerScore() : 0;
  const rank = typeof game.getTrainerRank === 'function' ? game.getTrainerRank(score).active : null;
  const labels = Object.fromEntries([
    'trainerCard', 'trainer', 'partner', 'favorites', ...TRAINER_CARD_THEMES, 'front', 'back', 'badges', 'tower',
    'pokedex', 'shinyPokedex', 'trainerScore', 'travel', 'leagueWon', 'shinyHunter', 'emptySlot', 'tagline',
  ].map(key => [key, trainerCardText(game, key)]));
  const stamps = Object.entries(game.badges ?? {})
    .filter(([key, value]) => key.startsWith('maitre_') && value)
    .slice(0, 2)
    .map(([key]) => ({ title: key.replace('maitre_', '').toUpperCase(), subtitle: labels.leagueWon ?? '' }));
  if ((game.stats?.shiniesObtained ?? 0) > 0) {
    stamps.push({ title: 'SHINY', subtitle: trainerCardText(game, 'shinyCount', { count: game.stats.shiniesObtained }) });
  }
  const favorites: (TrainerCardPokemon | null)[] = selected.favorites.map(pokemon);
  while (favorites.length < 8) favorites.push(null);
  return {
    language,
    name: game.getPlayerProfileName(),
    avatar: game.getPlayerProfileSpriteUrl(),
    title: preferences.title || trainerCardText(game, 'defaultTitle'),
    grade: { name: rank ? game.t(`statsUi.${rank.key}`) : '', color: rank?.color ?? '#94a3b8' },
    score,
    partner: selected.partner ? pokemon(selected.partner) : null,
    favorites,
    badges: Object.values(game.badges ?? {}).filter(Boolean).length,
    tower: Number(game.towerRecord) || 0,
    pokedex: { normal: percentage(normal.size), shiny: percentage(shiny.size) },
    stats: preferences.statKeys.map(key => ({ label: trainerCardText(game, `stat_${key}`), value: Number(game.stats?.[key]) || 0 })),
    stamps,
    preferences,
    labels,
  };
}
