import type { TrainerCardFormat, TrainerCardSide } from './trainerCardPreferences.ts';

export interface TrainerCardRect { x: number; y: number; width: number; height: number }
export interface TrainerCardLayout {
  width: number;
  height: number;
  partner: TrainerCardRect;
  favorites: TrainerCardRect[];
}

export function trainerCardLayout(format: TrainerCardFormat): TrainerCardLayout {
  const wide = format === 'landscape';
  const width = wide ? 960 : 480;
  const height = wide ? 600 : 860;
  const startX = wide ? 504 : 48;
  const startY = wide ? 224 : 554;
  const cellWidth = wide ? 95 : 91;
  const cellHeight = wide ? 112 : 84;
  return {
    width, height,
    partner: wide
      ? { x: 234, y: 238, width: 220, height: 253 }
      : { x: 218, y: 250, width: 222, height: 270 },
    favorites: Array.from({ length: 8 }, (_, i) => ({
      x: startX + (i % 4) * (cellWidth + 7),
      y: startY + Math.floor(i / 4) * (cellHeight + 8),
      width: cellWidth, height: cellHeight,
    })),
  };
}

const imageCache = new Map<string, Promise<HTMLImageElement>>();
const failedImages = new Set<string>();

/** The trainer CDN omits CORS headers; these are exact local copies of its profile sprites. */
export function trainerCardImageSource(url: string): string {
  const profile = PLAYER_TRAINER_SPRITES.find(entry => entry.url === url);
  const local: Record<string, string> = {
    red: 'img/trainer-profiles/red.png', leaf: 'img/trainer-profiles/leaf.png',
    ethan: 'img/trainer-profiles/ethan.png', lyra: 'img/trainer-profiles/lyra.png',
    brendan: 'img/trainer-profiles/brendan.png', may: 'img/trainer-profiles/may.png',
    lucas: 'img/trainer-profiles/lucas.png', dawn: 'img/trainer-profiles/dawn.png',
  };
  return profile ? local[profile.id] ?? url : url;
}

export function retryTrainerCardImages(): void {
  failedImages.forEach(url => imageCache.delete(url));
  failedImages.clear();
}

function imageForCard(url: string): Promise<HTMLImageElement> {
  const cached = imageCache.get(url);
  if (cached) return cached;
  const promise = new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    const timeout = setTimeout(() => { image.onload = null; image.onerror = null; reject(new Error('Sprite timeout')); }, 12000);
    image.onload = () => { clearTimeout(timeout); resolve(image); };
    image.onerror = () => { clearTimeout(timeout); reject(new Error('Sprite unavailable')); };
    image.src = trainerCardImageSource(url);
  });
  imageCache.set(url, promise);
  if (imageCache.size > 64) {
    const oldest = imageCache.keys().next().value ?? '';
    imageCache.delete(oldest);
    failedImages.delete(oldest);
  }
  void promise.catch(() => { if (imageCache.get(url) === promise) failedImages.add(url); });
  return promise;
}

function panel(ctx: CanvasRenderingContext2D, rect: TrainerCardRect, color: string | CanvasGradient, radius = 0, stroke?: string): void {
  ctx.beginPath();
  ctx.roundRect(rect.x, rect.y, rect.width, rect.height, radius);
  ctx.fillStyle = color;
  ctx.fill();
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
}

function text(ctx: CanvasRenderingContext2D, value: string, x: number, y: number, size = 14,
  color = '#24372f', width = 1000, align: CanvasTextAlign = 'left', family = 'Inter', weight = 600): number {
  let fitted = size;
  ctx.textAlign = align;
  ctx.textBaseline = 'alphabetic';
  ctx.font = `${weight} ${fitted}px "${family}"`;
  while (ctx.measureText(value).width > width && fitted > 7) {
    fitted -= 0.5;
    ctx.font = `${weight} ${fitted}px "${family}"`;
  }
  ctx.fillStyle = color;
  ctx.fillText(value, x, y, width);
  return Math.min(ctx.measureText(value).width, width);
}

function line(ctx: CanvasRenderingContext2D, x1: number, y1: number, x2: number, y2: number, color = '#a3b79f'): void {
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.stroke();
}

function sprite(ctx: CanvasRenderingContext2D, image: HTMLImageElement | undefined, rect: TrainerCardRect): void {
  if (!image) return;
  const scale = Math.min(rect.width / image.naturalWidth, rect.height / image.naturalHeight);
  const width = image.naturalWidth * scale;
  const height = image.naturalHeight * scale;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(image, rect.x + (rect.width - width) / 2, rect.y + (rect.height - height) / 2, width, height);
}

function pill(ctx: CanvasRenderingContext2D, label: string, x: number, y: number, bg: string, fg: string, size = 11, maxWidth = 1000): number {
  ctx.font = `700 ${size}px Inter`;
  const width = Math.min(ctx.measureText(label).width + 14, maxWidth);
  panel(ctx, { x, y, width, height: size + 10 }, bg, 3, '#00000066');
  text(ctx, label, x + 7, y + size + 3, size, fg, width - 10);
  return width;
}

function typePills(ctx: CanvasRenderingContext2D, pokemon: TrainerCardPokemon, cx: number, y: number, language: string): void {
  const types = [pokemon.type, pokemon.secondaryType].filter((type): type is string => !!type);
  const labels = types.map(type => formatPokemonTypeLabel(type, language));
  ctx.font = '700 10px Inter';
  const widths = labels.map(label => ctx.measureText(label).width + 14);
  let x = cx - (widths.reduce((sum, width) => sum + width, 0) + (types.length - 1) * 5) / 2;
  types.forEach((type, i) => {
    const colors = TYPE_COLORS[type] ?? TYPE_COLORS.normal;
    if (!colors) return;
    x += pill(ctx, labels[i] ?? type, x, y, colors.bg, colors.text, 10) + 5;
  });
}

function nameAndPrestige(ctx: CanvasRenderingContext2D, pokemon: TrainerCardPokemon, cx: number, y: number,
  width: number, star: HTMLImageElement | undefined, compact = false): void {
  const size = compact ? 10 : 13;
  const prestige = pokemon.prestige > 9999 ? formatNumber(pokemon.prestige) : String(pokemon.prestige);
  ctx.font = `750 ${size}px Inter`;
  const badgeWidth = ctx.measureText(prestige).width + 18;
  const nameWidth = Math.min(ctx.measureText(pokemon.name).width, width - badgeWidth - 5);
  const x = cx - (nameWidth + badgeWidth + 5) / 2;
  text(ctx, pokemon.name, x, y, size, compact ? '#f8fafc' : '#24372f', nameWidth, 'left', 'Inter', 750);
  panel(ctx, { x: x + nameWidth + 4, y: y - size, width: badgeWidth, height: size + 5 }, '#1e222b', 2);
  sprite(ctx, star, { x: x + nameWidth + 7, y: y - size + 2, width: size - 1, height: size - 1 });
  text(ctx, prestige, x + nameWidth + size + 8, y, size, '#fbbf24', badgeWidth - size - 4, 'left', 'Inter', 750);
}

/** Draws the same surface used by the live preview and by PNG exports. */
export async function renderTrainerCardCanvas(canvas: HTMLCanvasElement, model: TrainerCardModel,
  format: TrainerCardFormat, side: TrainerCardSide, scale = 2): Promise<{ missingSprites: number }> {
  if (side !== 'front' && side !== 'back') throw new Error('Only public trainer card faces can be exported');
  const layout = trainerCardLayout(format);
  const sceneUrl = trainerCardScene(model.preferences);
  const themeArt = trainerCardThemeArt(model.preferences.theme);
  const urls = [...new Set([
    ...(side === 'front' ? [model.avatar, 'img/prestige-star.png', model.partner?.sprite, ...model.favorites.map(p => p?.sprite)] : []),
    sceneUrl, themeArt,
  ].filter((url): url is string => !!url))];
  await document.fonts.ready;
  const loaded = await Promise.allSettled(urls.map(imageForCard));
  const images = new Map<string, HTMLImageElement>();
  loaded.forEach((result, index) => { if (result.status === 'fulfilled') images.set(urls[index] ?? '', result.value); });
  const missingSprites = loaded.filter(result => result.status === 'rejected').length;
  canvas.width = layout.width * scale;
  canvas.height = layout.height * scale;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas is unavailable');
  ctx.scale(scale, scale);
  const { width: w, height: h } = layout;
  const wide = format === 'landscape';
  const palette = trainerCardPalette(model.preferences.theme);
  const shell = model.preferences.accent ?? palette.shell;
  const label = (key: string) => model.labels[key] ?? '';
  const number = (value: number) => Math.abs(value) > 999999999 ? formatNumber(value) : new Intl.NumberFormat(model.language, { maximumFractionDigits: 1 }).format(value);
  panel(ctx, { x: 0, y: 0, width: w, height: h }, palette.dark, 30);
  drawTrainerCardShell(ctx, w, h, shell, model.preferences.frame, images.get(themeArt ?? sceneUrl ?? ''));
  ctx.strokeStyle = '#ffffff20'; ctx.strokeRect(9, 14, w - 18, 1);
  const lens = ctx.createRadialGradient(43, 33, 3, 48, 45, 24);
  lens.addColorStop(0, '#efffff'); lens.addColorStop(0.35, '#68d6e4'); lens.addColorStop(1, '#205d75');
  panel(ctx, { x: 22, y: 17, width: 54, height: 54 }, '#ecebdd', 27, palette.dark);
  panel(ctx, { x: 28, y: 23, width: 42, height: 42 }, lens, 21, '#245f78');
  ['#f67d7d', '#f2d775', '#a6c77a'].forEach((color, i) => panel(ctx, { x: 87 + i * 15, y: 24, width: 8, height: 8 }, color, 4, '#00000033'));
  text(ctx, 'POKETIME', w - 28, 44, 18, '#fff2e3', w / 2 - 25, 'right', 'Press Start 2P', 400);
  text(ctx, label('trainerCard').toUpperCase(), w - 28, 67, 10, '#fff2e3', w / 2 - 25, 'right', 'Inter', 750);
  drawTrainerCardBezel(ctx, { x: 18, y: 92, width: w - 36, height: h - 152 }, model.preferences.frame);
  panel(ctx, { x: 30, y: 113, width: w - 60, height: h - 183 }, palette.screen, 5, '#40544a');
  const scene = images.get(sceneUrl ?? '');
  if (side === 'back' && scene) {
    ctx.save(); ctx.globalAlpha = .055;
    trainerCardCover(ctx, scene, { x: 31, y: 147, width: w - 62, height: h - 247 }); ctx.restore();
  }
  [w / 2 - 5, w / 2 + 5].forEach(x => panel(ctx, { x, y: 101, width: 4, height: 4 }, '#9fa48f', 2));
  text(ctx, label(side).toUpperCase(), 46, 134, 11, '#516a58', 250, 'left', 'Press Start 2P', 400);
  text(ctx, 'POKÉDEX', w - 46, 134, 11, '#516a58', 110, 'right', 'Inter', 650);
  line(ctx, 31, 145, w - 31, 145);

  if (side === 'front') {
    text(ctx, model.name, 52, 190, 36, '#24372f', wide ? 390 : 375, 'left', 'Inter', 800);
    ctx.font = '700 11px Inter';
    const gradeWidth = ctx.measureText(model.grade.name).width + 14;
    const titleWidth = pill(ctx, model.title, 52, 207, '#252830', '#e2e8f0', 11, (wide ? 402 : w - 104) - gradeWidth - 7);
    pill(ctx, model.grade.name, 52 + titleWidth + 7, 207, '#1e222b', model.grade.color, 11);
    const hit = layout.partner;
    if (scene) drawTrainerCardScene(ctx, scene, { x: 45, y: 242, width: wide ? 410 : w - 90, height: wide ? 204 : 233 }, palette.screen, palette.accent, model.preferences.frame);
    if (model.preferences.background === 'radar') {
      const cx = hit.x + hit.width / 2;
      const cy = wide ? 342 : 355;
      [44, 88].forEach(radius => { ctx.beginPath(); ctx.arc(cx, cy, radius, 0, Math.PI * 2); ctx.strokeStyle = '#a9bda1'; ctx.stroke(); });
      line(ctx, cx - 98, cy, cx + 98, cy, '#b5c6ae');
    } else if (model.preferences.background === 'grid') {
      for (let x = 52; x < (wide ? 454 : w - 46); x += 24) line(ctx, x, 245, x, wide ? 445 : 473, '#b5c6ae66');
      for (let y = 245; y < (wide ? 445 : 473); y += 24) line(ctx, 52, y, wide ? 454 : w - 46, y, '#b5c6ae66');
    }
    if (model.partner?.dexNumber) text(ctx, String(model.partner.dexNumber).padStart(3, '0'), hit.x + hit.width - 8, 298, 72, '#b5c7aa', 155, 'right', 'Inter', 750);
    line(ctx, 52, wide ? 446 : 475, wide ? 454 : w - 46, wide ? 446 : 475);
    sprite(ctx, images.get(model.avatar), { x: 50, y: wide ? 270 : 286, width: 138, height: wide ? 170 : 180 });
    text(ctx, label('trainer').toUpperCase(), 67, wide ? 469 : 501, 10, '#516a58', 125, 'left', 'Inter', 600);
    if (model.partner) {
      if (scene || model.partner.shiny) drawTrainerCardAura(ctx, { x: hit.x, y: hit.y, width: hit.width, height: wide ? 207 : 225 }, palette.accent, model.partner.shiny);
      sprite(ctx, images.get(model.partner.sprite), { x: hit.x, y: hit.y, width: hit.width, height: wide ? 207 : 225 });
      nameAndPrestige(ctx, model.partner, hit.x + hit.width / 2, wide ? 467 : 501, hit.width, images.get('img/prestige-star.png'));
      typePills(ctx, model.partner, hit.x + hit.width / 2, wide ? 477 : 510, model.language);
    }
    if (wide) line(ctx, 480, 145, 480, h - 98);
    else line(ctx, 31, 537, w - 31, 537);
    text(ctx, label('favorites').toUpperCase(), wide ? 504 : 48, wide ? 184 : 545, 10, '#516a58', wide ? 390 : 382, 'left', 'Inter', 750);
    layout.favorites.forEach((rect, i) => {
      const pokemon = model.favorites[i];
      panel(ctx, rect, '#1e222b', 5, '#4b5363');
      text(ctx, String(i + 1).padStart(2, '0'), rect.x + 5, rect.y + 12, 8, '#aab3c5', 25);
      if (!pokemon) {
        text(ctx, '+', rect.x + rect.width / 2, rect.y + rect.height / 2 + 2, 26, '#aab3c5', rect.width - 12, 'center');
        text(ctx, label('emptySlot'), rect.x + rect.width / 2, rect.y + rect.height - 12, 9, '#aab3c5', rect.width - 8, 'center');
        return;
      }
      sprite(ctx, images.get(pokemon.sprite), { x: rect.x + 5, y: rect.y + 6, width: rect.width - 10, height: rect.height - 30 });
      nameAndPrestige(ctx, pokemon, rect.x + rect.width / 2, rect.y + rect.height - 13, rect.width - 8, images.get('img/prestige-star.png'), true);
      const primary = TYPE_COLORS[pokemon.type]?.bg ?? '#868e96';
      const secondary = TYPE_COLORS[pokemon.secondaryType ?? pokemon.type]?.bg ?? primary;
      panel(ctx, { x: rect.x + 1, y: rect.y + rect.height - 4, width: rect.width / 2, height: 3 }, primary);
      panel(ctx, { x: rect.x + rect.width / 2, y: rect.y + rect.height - 4, width: rect.width / 2 - 1, height: 3 }, secondary);
    });
  } else {
    text(ctx, model.name, 52, 182, 30, '#24372f', w - 110, 'left', 'Inter', 800);
    text(ctx, model.title, 52, 207, 12, '#516a58', w - 110);
    const scoreRect = { x: 52, y: 229, width: wide ? 398 : w - 104, height: 76 };
    panel(ctx, scoreRect, '#1e222b', 6, '#4b5363');
    text(ctx, label('trainerScore'), 66, 252, 12, '#e2e8f0', 150);
    pill(ctx, model.grade.name, 66, 264, model.grade.color + '22', model.grade.color, 10);
    text(ctx, number(model.score), scoreRect.x + scoreRect.width - 13, 279, 34, '#fbbf24', scoreRect.width - 160, 'right', 'Inter', 800);
    const recordsY = wide ? 329 : 339;
    const rightX = wide ? 271 : w / 2 + 17;
    text(ctx, label('badges'), 52, recordsY, 11, '#516a58', 180);
    text(ctx, number(model.badges), 52, recordsY + 45, 44, '#24372f', 170, 'left', 'Inter', 750);
    text(ctx, label('tower'), rightX, recordsY, 11, '#516a58', 170);
    text(ctx, number(model.tower), rightX, recordsY + 45, 44, '#24372f', 170, 'left', 'Inter', 750);
    let dexY = wide ? 405 : 414;
    const dexWidth = wide ? 398 : w - 104;
    const dex = (title: string, value: number, color: string) => {
      text(ctx, title, 52, dexY, 11, '#516a58', dexWidth - 85);
      text(ctx, number(value) + ' %', 52 + dexWidth, dexY, 18, '#24372f', 100, 'right', 'Inter', 750);
      panel(ctx, { x: 52, y: dexY + 9, width: dexWidth, height: 6 }, '#c5d4bb', 2);
      if (value > 0) panel(ctx, { x: 52, y: dexY + 9, width: dexWidth * Math.min(100, value) / 100, height: 6 }, color, 2);
      dexY += 47;
    };
    if (model.preferences.pokedexMode !== 'shiny') dex(label('pokedex'), model.pokedex.normal, '#557951');
    if (model.preferences.pokedexMode !== 'normal') dex(label('shinyPokedex'), model.pokedex.shiny, '#8d733d');
    if (wide) line(ctx, 480, 220, 480, h - 98);
    const statsX = wide ? 507 : 52;
    const statsY = wide ? 248 : 548;
    const statsWidth = wide ? 395 : w - 104;
    model.stats.forEach((stat, i) => {
      const x = statsX + (i % 2) * (statsWidth / 2 + 5);
      const y = statsY + Math.floor(i / 2) * (wide ? 86 : 74);
      line(ctx, x, y - 17, x + statsWidth / 2 - 13, y - 17);
      text(ctx, stat.label, x, y, 11, '#516a58', statsWidth / 2 - 16);
      text(ctx, number(stat.value), x, y + 35, 27, '#24372f', statsWidth / 2 - 14, 'left', 'Inter', 750);
    });
    if (model.stamps.length > 0) {
      const x = wide ? 507 : 52;
      const y = wide ? 435 : 711;
      const width = wide ? 395 : w - 104;
      text(ctx, label('travel').toUpperCase(), x, y - 10, 10, '#516a58', width);
      model.stamps.slice(0, 3).forEach((stamp, i, stamps) => {
        const sw = (width - 14) / stamps.length;
        panel(ctx, { x: x + i * (sw + 7), y, width: sw, height: 44 }, '#dce8d6', 3, '#7d967a');
        text(ctx, stamp.title, x + i * (sw + 7) + sw / 2, y + 18, 11, '#4d6c4f', sw - 12, 'center', 'Press Start 2P', 400);
        text(ctx, stamp.subtitle, x + i * (sw + 7) + sw / 2, y + 34, 8, '#4d6c4f', sw - 10, 'center');
      });
    }
  }
  line(ctx, 31, h - 98, w - 31, h - 98);
  text(ctx, label(model.preferences.theme).toUpperCase(), 46, h - 80, 9, '#516a58', w - 170, 'left', 'Inter', 750);
  text(ctx, side === 'front' ? '01 / 02' : '02 / 02', w - 46, h - 80, 10, '#516a58', 90, 'right', 'Inter', 650);
  panel(ctx, { x: 27, y: h - 43, width: 28, height: 28 }, '#273a38', 14, '#67796f');
  panel(ctx, { x: 69, y: h - 40, width: 30, height: 5 }, '#e2c367', 2);
  panel(ctx, { x: 105, y: h - 40, width: 30, height: 5 }, '#769ca1', 2);
  text(ctx, label('tagline').toUpperCase(), w - 48, h - 24, 8, '#fff2e3', w - 205, 'right', 'Inter', 750);
  return { missingSprites };
}

export async function trainerCardPng(model: TrainerCardModel, format: TrainerCardFormat, side: TrainerCardSide): Promise<Blob> {
  const canvas = document.createElement('canvas');
  const result = await renderTrainerCardCanvas(canvas, model, format, side, 3);
  if (result.missingSprites) throw new Error('Card sprites are unavailable');
  return new Promise((resolve, reject) => canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error('PNG unavailable')), 'image/png'));
}
