import { TYPE_COLORS } from '../../constants/core.ts';
import type { TrainerCardPreferences, TrainerCardTheme, TrainerCardFrame, TrainerCardBackground } from './trainerCardPreferences.ts';

/** Existing game artworks, kept local so the preview and PNG work with the same assets. */
const art = (name: string) => `img/trainer-card-art/${name}.webp`;
export const TRAINER_CARD_TYPE_ART: Record<string, string> = {
  normal: art('skin-27'), fire: art('bronze-hunter'), water: art('skin-22'), grass: art('skin-20'),
  electric: art('skin-36'), ice: art('skin-45'), fighting: art('skin-24'), poison: art('skin-32'),
  ground: art('skin-46'), flying: art('skin-3'), psychic: art('skin-7'), bug: art('skin-4'),
  rock: art('skin-61'), ghost: art('skin-14'), dragon: art('skin-40'), dark: art('skin-66'),
  steel: art('skin-67'), fairy: art('skin-23'),
};
export const TRAINER_CARD_REGION_ART: Partial<Record<TrainerCardBackground, string>> = {
  kanto: art('skin-34'), johto: art('shiny-prisma'), hoenn: art('skin-40'), sinnoh: art('skin-38'),
  unova: art('skin-62'), kalos: art('skin-23'), alola: art('skin-31'),
};
export const TRAINER_CARD_FRAME_ART: Record<TrainerCardFrame, string> = {
  standard: art('skin-30'), bronze: art('bronze-hunter'), gold: art('living-legend'), prism: art('shiny-prisma'),
  tower: art('skin-65'), starlight: art('skin-53'), legend: art('skin-38'),
};

export function mixTrainerCardColor(first: string, second: string, amount: number): string {
  const channels = [1, 3, 5].map(offset => Math.round(parseInt(first.slice(offset, offset + 2), 16) * (1 - amount)
    + parseInt(second.slice(offset, offset + 2), 16) * amount).toString(16).padStart(2, '0'));
  return `#${channels.join('')}`;
}

export function trainerCardPalette(theme: TrainerCardTheme): { shell: string; dark: string; screen: string; accent: string } {
  if (theme.startsWith('type_')) {
    const accent = TYPE_COLORS[theme.slice(5)]?.bg ?? '#868e96';
    return { shell: mixTrainerCardColor(accent, '#18262d', .38), dark: mixTrainerCardColor(accent, '#101820', .72), screen: mixTrainerCardColor(accent, '#f5f2e8', .94), accent };
  }
  return theme === 'league' ? { shell: '#9c7428', dark: '#4d3915', screen: '#f1eddf', accent: '#e2bd64' }
    : theme === 'shiny' ? { shell: '#625487', dark: '#302641', screen: '#eee8f3', accent: '#d8b8eb' }
      : { shell: '#c53545', dark: '#9b2435', screen: '#e5eee2', accent: '#a3c79b' };
}

export function trainerCardThemeArt(theme: TrainerCardTheme): string | null {
  return theme.startsWith('type_') ? TRAINER_CARD_TYPE_ART[theme.slice(5)] ?? null
    : theme === 'league' ? TRAINER_CARD_FRAME_ART.gold : theme === 'shiny' ? TRAINER_CARD_FRAME_ART.prism : null;
}

export function trainerCardScene(preferences: TrainerCardPreferences): string | null {
  if (preferences.background === 'plain') return null;
  return TRAINER_CARD_REGION_ART[preferences.background] ?? trainerCardThemeArt(preferences.theme);
}

export function trainerCardCosmeticImage(kind: 'theme' | 'frame' | 'background', id: string): string {
  if (kind === 'frame') return TRAINER_CARD_FRAME_ART[id as TrainerCardFrame];
  if (kind === 'background') return TRAINER_CARD_REGION_ART[id as TrainerCardBackground] ?? art('skin-30');
  return trainerCardThemeArt(id as TrainerCardTheme) ?? art('skin-30');
}

export function trainerCardCosmeticThumbnail(url: string): string {
  return url.replace(/\.webp$/, '-thumb.webp');
}
