<script lang="ts">
  import { game } from '../../gameManager.js';
  import type { GameRuntime } from '../types/game.js';
  import { fetiche } from '../stores/fetiche.svelte.ts';
  import { masteryProfileTab } from '../stores/masteryProfileTab.svelte.ts';
  import { notifyFeticheChanged } from '../lib/feticheSnapshot.ts';
  import FetichePanel from './FetichePanel.svelte';
  import TrainerCard from './TrainerCard.svelte';
  import { playGameSfx } from '../audio/audioDirector.ts';

  let activeTab = $derived(masteryProfileTab.active);
  let feticheSnap = $derived(fetiche.snapshot);
  let showFeticheBadge = $derived(feticheSnap.headerHungryBadge);
  let feticheUnlocked = $derived(feticheSnap.featureUnlocked);

  let tabProfilLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Profil';
    void gm.language;
    return gm.t?.('fetiche.tabProfil') ?? 'Profil';
  });

  let tabTalentsLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Talents';
    void gm.language;
    return gm.t?.('fetiche.tabTalents') ?? 'Talents';
  });

  let tabRadarsLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Radars';
    void gm.language;
    return gm.t?.('fetiche.tabRadars') ?? 'Radars';
  });

  let tabFeticheLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Fétiche';
    void gm.language;
    return gm.t?.('fetiche.tabFetiche') ?? 'Fétiche';
  });

  let tabCardLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Card';
    void gm.language;
    return gm.t?.('fetiche.tabCard') ?? 'Card';
  });

  let masteryTabsAriaLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!gm) return 'Profil et Fétiche';
    void gm.language;
    return gm.t?.('fetiche.masteryTabsLabel') ?? 'Profil et Fétiche';
  });

  let feticheTabAriaLabel = $derived.by((): string => {
    const gm = game as GameRuntime | null;
    if (!showFeticheBadge) return tabFeticheLabel;
    void gm?.language;
    return gm?.t?.('fetiche.tabFeticheHungry') ?? `${tabFeticheLabel} — a faim`;
  });

  function selectTab(tab: 'profil' | 'radars' | 'fetiche' | 'card'): void {
    const gm = game as GameRuntime | null;
    if (tab === 'fetiche' && !feticheUnlocked) {
      tab = 'profil';
    }
    const enteringFetiche = tab === 'fetiche' && masteryProfileTab.active !== 'fetiche';
    masteryProfileTab.active = tab;
    if (enteringFetiche) playGameSfx('modal');
    if (tab === 'fetiche') {
      if (gm?.feticheState) {
        gm.feticheState.moodChangedPending = false;
      }
      if (gm && typeof gm.openFetichePanel === 'function') {
        gm.openFetichePanel();
      }
    } else if (gm) {
      notifyFeticheChanged(gm, { force: true, visible: false });
    }
    if (tab === 'card' && gm && typeof gm.renderMasteryTrainerCard === 'function') {
      gm.renderMasteryTrainerCard();
    }
  }
</script>

<div class={['stats-content mastery-frame-surface', `mastery-tab-${activeTab}`]} data-action="stopPropagation" data-action-stop style="max-width: 780px; width: min(92vw, 780px);">
  <div class="mastery-sticky-head">
  <div class="stats-header mastery-profile-stats-header">
    <div class="mastery-profile-tabs" role="tablist" aria-label={masteryTabsAriaLabel}>
      <button
        id="masteryTabProfil"
        type="button"
        class={['mastery-profile-tab', { active: activeTab === 'profil' }]}
        role="tab"
        aria-selected={activeTab === 'profil'}
        aria-controls="masteryDisplay"
        onclick={() => selectTab('profil')}
      ><span class="mastery-tab-label-wide">{tabProfilLabel}</span><span class="mastery-tab-label-narrow">{tabTalentsLabel}</span></button>
      <button
        id="masteryTabRadars"
        type="button"
        class={['mastery-profile-tab mastery-profile-tab-radars', { active: activeTab === 'radars' }]}
        role="tab"
        aria-selected={activeTab === 'radars'}
        aria-controls="masteryDisplay"
        onclick={() => selectTab('radars')}
      >{tabRadarsLabel}</button>
      {#if feticheUnlocked}
      <button
        id="masteryTabFetiche"
        type="button"
        class={['mastery-profile-tab mastery-profile-tab-fetiche', { active: activeTab === 'fetiche' }]}
        role="tab"
        aria-selected={activeTab === 'fetiche'}
        aria-controls="masteryFetichePanel"
        aria-label={feticheTabAriaLabel}
        onclick={() => selectTab('fetiche')}
      >
        {tabFeticheLabel}
        {#if showFeticheBadge}
          <span class="mastery-profile-tab-badge" aria-hidden="true"></span>
        {/if}
      </button>
      {/if}
      <button
        id="masteryTabCard"
        type="button"
        class={['mastery-profile-tab mastery-profile-tab-card', { active: activeTab === 'card' }]}
        role="tab"
        aria-selected={activeTab === 'card'}
        aria-controls="masteryTrainerCardPanel"
        onclick={() => selectTab('card')}
      >{tabCardLabel}</button>
    </div>
    <div class="mastery-header-actions">
      <button
        id="masteryHeaderResetBtn"
        type="button"
        class="btn-ghost mastery-header-reset-btn"
        data-action="resetMasteryPoints"
        hidden={activeTab !== 'profil'}
      >Réinitialiser</button>
      <button type="button" class="stats-close" data-action="closeMasteryModal">&#10005;</button>
    </div>
  </div>
  <div id="masteryPointsSlot" hidden={activeTab !== 'profil'}></div>
  </div>
  <h2 id="masteryTitleLabel" class="mastery-frame-title mastery-profile-title-fallback" hidden>Amelioration du Joueur</h2>
  <div
    id="masteryDisplay"
    role="tabpanel"
    aria-labelledby="masteryTabProfil"
    hidden={activeTab === 'fetiche' || activeTab === 'card'}
  ></div>
  <div
    id="masteryFetichePanel"
    role="tabpanel"
    aria-labelledby="masteryTabFetiche"
    hidden={activeTab !== 'fetiche'}
  >
    <FetichePanel />
  </div>
  <div
    id="masteryTrainerCardPanel"
    role="tabpanel"
    aria-labelledby="masteryTabCard"
    hidden={activeTab !== 'card'}
  >
    {#if activeTab === 'card'}<TrainerCard />{/if}
  </div>
</div>
