import { mixTrainerCardColor } from './trainerCardCosmetics.ts';
import type { TrainerCardFrame } from './trainerCardPreferences.ts';
import type { TrainerCardRect } from './trainerCardCanvas.ts';

export function trainerCardCover(ctx: CanvasRenderingContext2D, image: HTMLImageElement, rect: TrainerCardRect): void {
  const ratio = Math.max(rect.width / image.naturalWidth, rect.height / image.naturalHeight);
  const sw = rect.width / ratio;
  const sh = rect.height / ratio;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(image, (image.naturalWidth - sw) / 2, (image.naturalHeight - sh) / 2, sw, sh, rect.x, rect.y, rect.width, rect.height);
}

function clip(ctx: CanvasRenderingContext2D, rect: TrainerCardRect, radius: number): void {
  ctx.beginPath(); ctx.roundRect(rect.x, rect.y, rect.width, rect.height, radius); ctx.clip();
}

function star(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, color: string): void {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.moveTo(x, y - size); ctx.quadraticCurveTo(x + 1, y - 1, x + size, y);
  ctx.quadraticCurveTo(x + 1, y + 1, x, y + size); ctx.quadraticCurveTo(x - 1, y + 1, x - size, y);
  ctx.quadraticCurveTo(x - 1, y - 1, x, y - size); ctx.fill();
}

function foil(ctx: CanvasRenderingContext2D, rect: TrainerCardRect, opacity: number): void {
  const gradient = ctx.createLinearGradient(rect.x, rect.y, rect.x + rect.width, rect.y + rect.height);
  ['#d5b6f0', '#95dbe4', '#eff9c1', '#f0bed8', '#a4b5f0', '#a0e7cf'].forEach((color, i) => gradient.addColorStop(i / 5, color));
  ctx.save(); ctx.globalAlpha = opacity; ctx.fillStyle = gradient; ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
  ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1;
  for (let x = rect.x - rect.height; x < rect.x + rect.width; x += 27) {
    ctx.beginPath(); ctx.moveTo(x, rect.y); ctx.lineTo(x + rect.height, rect.y + rect.height); ctx.stroke();
  }
  ctx.restore();
}

/** Static, deterministic foil and grain: identical in the preview and the downloaded PNG. */
export function drawTrainerCardShell(ctx: CanvasRenderingContext2D, width: number, height: number,
  shell: string, frame: TrainerCardFrame, artwork?: HTMLImageElement): void {
  const rect = { x: 1, y: 1, width: width - 2, height: height - 8 };
  ctx.save(); clip(ctx, rect, 29);
  const metal = ctx.createLinearGradient(0, 0, width, height);
  metal.addColorStop(0, mixTrainerCardColor(shell, '#ffffff', .22)); metal.addColorStop(.24, shell);
  metal.addColorStop(.58, mixTrainerCardColor(shell, '#080d18', .28)); metal.addColorStop(1, mixTrainerCardColor(shell, '#ffffff', .08));
  ctx.fillStyle = metal; ctx.fillRect(0, 0, width, height);
  if (artwork) {
    ctx.globalAlpha = .22; trainerCardCover(ctx, artwork, rect); ctx.globalAlpha = 1;
    const shade = ctx.createLinearGradient(0, 0, width, 0); shade.addColorStop(0, '#0a1019aa'); shade.addColorStop(.5, '#0a101977'); shade.addColorStop(1, '#0a101944');
    ctx.fillStyle = shade; ctx.fillRect(0, 0, width, 92);
  }
  if (frame === 'prism' || frame === 'starlight' || frame === 'legend') foil(ctx, rect, .18);
  // Fine engraved grain, rather than a flat tint. Fixed coordinates keep exports reproducible.
  for (let i = 0; i < 1800; i++) {
    ctx.fillStyle = i % 3 ? '#ffffff0a' : '#00000012';
    ctx.fillRect((i * 73.17) % width, (i * 47.71) % height, i % 4 === 0 ? 3 : .65, .65);
  }
  ctx.strokeStyle = '#fff5d84d'; ctx.lineWidth = 1; ctx.beginPath(); ctx.roundRect(4, 4, width - 8, height - 15, 26); ctx.stroke();
  for (let y = 164; y < height - 115; y += 22) {
    ctx.strokeStyle = '#ffffff16'; ctx.beginPath(); ctx.moveTo(7, y); ctx.lineTo(13, y - 5); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(width - 13, y); ctx.lineTo(width - 7, y - 5); ctx.stroke();
  }
  ctx.restore();
}

export function drawTrainerCardBezel(ctx: CanvasRenderingContext2D, rect: TrainerCardRect, frame: TrainerCardFrame): void {
  const colors: Record<TrainerCardFrame, string[]> = {
    standard: ['#f1f0e5', '#aaa994', '#e2e3d5'], bronze: ['#f2c299', '#865132', '#cd936a'],
    gold: ['#fff0af', '#98712c', '#f0d887'], prism: ['#e6d3f4', '#8ac9ce', '#efd9a5'],
    tower: ['#85939f', '#253344', '#afc4cd'], starlight: ['#a9b6e7', '#404b7f', '#e3d4aa'],
    legend: ['#fff8da', '#bc9452', '#fff1be'],
  };
  const stops = colors[frame];
  const metal = ctx.createLinearGradient(rect.x, rect.y, rect.x + rect.width, rect.y + rect.height);
  stops.forEach((color, i) => metal.addColorStop(i / (stops.length - 1), color));
  ctx.save(); clip(ctx, rect, 14); ctx.fillStyle = metal; ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
  if (frame === 'prism' || frame === 'legend') foil(ctx, rect, .55);
  ctx.strokeStyle = '#fffbe580'; ctx.lineWidth = 1; ctx.beginPath(); ctx.roundRect(rect.x + 3, rect.y + 3, rect.width - 6, rect.height - 6, 11); ctx.stroke();
  if (frame === 'tower') {
    ctx.strokeStyle = '#8ee7f1aa'; ctx.lineWidth = 1;
    for (const x of [rect.x + 6, rect.x + rect.width - 6]) {
      ctx.beginPath(); ctx.moveTo(x, rect.y + 28); ctx.lineTo(x, rect.y + rect.height - 28); ctx.stroke();
      for (let y = rect.y + 36; y < rect.y + rect.height - 15; y += 38) ctx.strokeRect(x - 2, y, 4, 4);
    }
  } else if (frame !== 'standard') {
    const color = frame === 'starlight' ? '#fff4c8' : '#fffae0bb';
    for (let y = rect.y + 35; y < rect.y + rect.height - 10; y += frame === 'starlight' ? 33 : 48) {
      star(ctx, rect.x + 6, y, frame === 'legend' ? 4 : 2.5, color);
      star(ctx, rect.x + rect.width - 6, y + 12, 2.5, color);
    }
  }
  if (frame === 'legend') {
    const cx = rect.x + rect.width / 2;
    ctx.fillStyle = '#83622c'; ctx.beginPath(); ctx.moveTo(cx - 13, rect.y + 10); ctx.lineTo(cx - 15, rect.y + 4);
    ctx.lineTo(cx - 6, rect.y + 7); ctx.lineTo(cx, rect.y + 2); ctx.lineTo(cx + 6, rect.y + 7);
    ctx.lineTo(cx + 15, rect.y + 4); ctx.lineTo(cx + 13, rect.y + 10); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

export function drawTrainerCardScene(ctx: CanvasRenderingContext2D, image: HTMLImageElement, rect: TrainerCardRect,
  screen: string, accent: string, frame: TrainerCardFrame): void {
  ctx.save(); clip(ctx, rect, 7);
  ctx.globalAlpha = .22;
  trainerCardCover(ctx, image, rect);
  ctx.globalAlpha = 1;
  const mist = ctx.createLinearGradient(rect.x, 0, rect.x + rect.width, 0);
  mist.addColorStop(0, screen + 'b8'); mist.addColorStop(.4, screen + '66'); mist.addColorStop(1, screen + '25');
  ctx.fillStyle = mist; ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
  const fade = ctx.createLinearGradient(0, rect.y + rect.height * .6, 0, rect.y + rect.height);
  fade.addColorStop(0, screen + '00'); fade.addColorStop(1, screen + 'd9');
  ctx.fillStyle = fade; ctx.fillRect(rect.x, rect.y, rect.width, rect.height);
  if (frame === 'prism' || frame === 'starlight' || frame === 'legend') {
    foil(ctx, rect, .035);
    for (let i = 0; i < 12; i++) star(ctx, rect.x + 16 + (i * 61) % (rect.width - 32), rect.y + 12 + (i * 43) % (rect.height - 28), i % 3 ? 2 : 4, '#fffbe466');
  }
  ctx.strokeStyle = accent + '30'; ctx.lineWidth = 1; ctx.strokeRect(rect.x + .5, rect.y + .5, rect.width - 1, rect.height - 1);
  ctx.restore();
}

export function drawTrainerCardAura(ctx: CanvasRenderingContext2D, rect: TrainerCardRect, accent: string, shiny: boolean): void {
  ctx.save();
  const glow = ctx.createRadialGradient(rect.x + rect.width / 2, rect.y + rect.height * .55, 10, rect.x + rect.width / 2, rect.y + rect.height * .55, rect.width * .58);
  glow.addColorStop(0, (shiny ? '#f5d685' : accent) + '55'); glow.addColorStop(1, accent + '00');
  ctx.fillStyle = glow; ctx.fillRect(rect.x - 20, rect.y, rect.width + 40, rect.height);
  ctx.fillStyle = '#172e291c'; ctx.beginPath(); ctx.ellipse(rect.x + rect.width / 2, rect.y + rect.height - 9, rect.width * .3, 7, 0, 0, Math.PI * 2); ctx.fill();
  if (shiny) { star(ctx, rect.x + 18, rect.y + 44, 6, '#fff7d4'); star(ctx, rect.x + rect.width - 24, rect.y + 86, 4, '#fff7d4'); }
  ctx.restore();
}
